def docs():
    return {role: r.document(raw) for role, raw in RAW_BODIES.items()}


def inputs(root, selected=None):
    folder = root / "inputs"
    folder.mkdir()
    bodies = RAW_BODIES
    if selected is not None:
        r.repaired_pins(selected)
        bodies = {role: r.canonical(value) for role, value in selected.items()}
        bodies["historical_foreign_outcome_reference"] = RAW_BODIES[
            "historical_foreign_outcome_reference"
        ]
    rows = []
    for index, role in enumerate(r.ROLES):
        path = folder / f"{index:02d}-{role}.json"
        path.write_bytes(bodies[role])
        rows.append(
            {
                "role": role,
                "path": str(path),
                "sha256": r.sha(bodies[role]),
                "size_bytes": len(bodies[role]),
            }
        )
    path = folder / "input_manifest.json"
    path.write_bytes(r.canonical({"schema": r.INPUT_SCHEMA, "selected_files": rows}))
    return path, rows


class ArtifactPayloadTests(unittest.TestCase):
    def setUp(self):
        self.temporary = tempfile.TemporaryDirectory()
        self.root = Path(self.temporary.name).resolve()
        self.manifest, self.rows = inputs(self.root)
        self.output = self.root / "output"

    def tearDown(self):
        self.temporary.cleanup()

    def receive(self):
        return r.audit(self.manifest, self.output)

    def refuse(self, fragment=None):
        with self.assertRaises((r.Refusal, OSError)) as result:
            self.receive()
        if fragment:
            self.assertIn(fragment, str(result.exception))

    def manifest_change(self, action):
        value = json.loads(self.manifest.read_bytes())
        action(value)
        self.manifest.write_bytes(r.canonical(value))

    def test_complete_offline_receive_and_exact_population(self):
        report = self.receive()
        self.assertEqual(report["status"], "passed")
        self.assertEqual(len(list(self.output.rglob("*"))), 19)
        self.assertEqual(report["custody"]["closing_raw_body_count"], 35)
        for key in r.TRUE:
            self.assertIs(report[key], True)
        for key in r.FALSE:
            self.assertIs(report[key], False)
        for key in r.ZERO:
            self.assertEqual(report[key], 0)
        for row in report["selected_files"]:
            self.assertEqual(
                Path(row["path"]).read_bytes(), Path(row["retained_copy"]["path"]).read_bytes()
            )
        self.assertEqual(json.loads((self.output / r.REPORT_NAME).read_bytes()), report)

    def test_original_unknown_and_bounded_typed_statuses(self):
        report = self.receive()
        cases = report["native_attempt"]["cases"]
        self.assertEqual([c["generic_result_status"] for c in cases], ["unknown", "unknown"])
        self.assertEqual([c["typed_result_status"] for c in cases], ["satisfied", "violated"])
        self.assertTrue(all(c["typed_authority"] == "model_check" for c in cases))
        self.assertTrue(all(c["output_digest_algorithm_rederived"] is False for c in cases))

    def test_artifact3_default64_and_historical_reference_remain_distinct(self):
        report = self.receive()
        self.assertEqual(report["native_attempt"]["actual_model_command_steps"], 3)
        self.assertTrue(all(x["compile_max_steps"] == 3 for x in report["artifacts"]))
        self.assertTrue(all(x["compiler_default_max_steps"] == 64 for x in report["decoder_cases"]))
        old = report["historical_foreign_reference"]
        self.assertFalse(old["initial_failed"]["accepted"])
        self.assertEqual(old["initial_failed"]["native_phase_count"], 3)
        self.assertEqual(old["accepted"]["native_phase_count"], 6)
        self.assertFalse(old["phase_counts_added_to_artifact_increment"])
        self.assertEqual(report["native_attempt"]["recorded_native_phase_count"], 6)

    def test_positive_repaired_metadata_projection(self):
        selected = docs()
        result = r.reconcile(selected, r.repaired_pins(selected))
        self.assertEqual(result["qualification"]["selected_test_count"], 2015)
        self.assertFalse(result["qualification"]["counts_additive"])

    def test_closed_unknown_manifest_field(self):
        self.manifest_change(lambda m: m.update(authority=True))
        self.refuse("closed fields")

    def test_reordered_roles(self):
        self.manifest_change(lambda m: m["selected_files"].reverse())
        self.refuse("typed ordered")

    def test_missing_role(self):
        self.manifest_change(lambda m: m["selected_files"].pop())
        self.refuse("finite ordered")

    def test_boolean_selected_size(self):
        self.manifest_change(lambda m: m["selected_files"][0].update(size_bytes=True))
        self.refuse("typed ordered")

    def test_corrupt_selected_raw_digest(self):
        path = Path(self.rows[0]["path"])
        path.write_bytes(path.read_bytes() + b" ")
        self.refuse("exact selected raw")

    def test_symlink_selected_file(self):
        path = Path(self.rows[1]["path"])
        held = self.root / "held.json"
        path.rename(held)
        path.symlink_to(held)
        self.refuse("canonical selected path")

    def test_symlink_selected_parent(self):
        alias = self.root / "alias"
        alias.symlink_to(self.root / "inputs", target_is_directory=True)
        self.manifest_change(
            lambda m: m["selected_files"][0].update(
                path=str(alias / Path(self.rows[0]["path"]).name)
            )
        )
        self.refuse("canonical selected path")

    def test_hardlink_physical_alias(self):
        a, b = Path(self.rows[0]["path"]), Path(self.rows[1]["path"])
        b.unlink()
        os.link(a, b)
        self.manifest_change(
            lambda m: m["selected_files"][1].update(
                sha256=self.rows[0]["sha256"], size_bytes=self.rows[0]["size_bytes"]
            )
        )
        self.refuse("physical aliases")

    def test_fifo_selected_file(self):
        path = Path(self.rows[0]["path"])
        path.unlink()
        os.mkfifo(path)
        self.refuse("regular selected body")

    def test_existing_output(self):
        self.output.mkdir()
        self.refuse("fresh output")

    def test_dangling_output_symlink(self):
        self.output.symlink_to(self.root / "absent")
        self.refuse("fresh output")

    def test_output_overlaps_selected_directory(self):
        self.output = self.root / "inputs" / "output"
        self.refuse("separated")

    def test_relative_selected_path(self):
        self.manifest_change(lambda m: m["selected_files"][0].update(path="relative.json"))
        self.refuse("distinct absolute")

    def test_duplicate_json_field(self):
        self.manifest.write_bytes(b'{"schema":"x","schema":"x","selected_files":[]}')
        self.refuse("duplicate JSON field")

    def test_nonfinite_json(self):
        self.manifest.write_bytes(b'{"schema":NaN,"selected_files":[]}')
        self.refuse("non-finite")

    def test_json_depth_bound(self):
        self.manifest.write_bytes(b"[" * 33 + b"0" + b"]" * 33)
        self.refuse("nesting bound")

    def test_json_node_bound(self):
        with self.assertRaises(r.Refusal):
            r.document(b"[" + b"0," * 100000 + b"0]")

    def test_json_integer_bound(self):
        with self.assertRaises(r.Refusal):
            r.document(str(2**63).encode())

    def test_surrogate_json(self):
        with self.assertRaises(r.Refusal):
            r.document(b'"\\ud800"')

    def test_late_original_inode_replacement(self):
        original = r.Capture.stable
        changed = False

        def replace(capture):
            nonlocal changed
            if not changed:
                target = Path(self.rows[0]["path"])
                held = target.with_suffix(".replacement")
                held.write_bytes(target.read_bytes())
                held.replace(target)
                changed = True
            return original(capture)

        with patch.object(r.Capture, "stable", replace):
            self.refuse("physical identity")

