    def test_serialization_report_cap(self):
        with patch.object(r, "MAX_REPORT", 100):
            self.refuse("report serialization cap")

    def test_manifest_cap(self):
        with patch.object(r, "MAX_MANIFEST", 100):
            self.refuse("regular selected body/cap")

    def test_closed_nested_unknown_field(self):
        selected = docs()
        selected["native_lifecycle_audit"][0]["result"]["authenticated"] = True
        with self.assertRaises(r.Refusal):
            r.reconcile(selected, r.repaired_pins(selected))

    def test_repaired_original_body_forgeries_through_receiver(self):
        selected = docs()
        selected["native_result"]["scope"]["native_v2_execution"] = True
        folder = self.root / "repaired"
        folder.mkdir()
        self.manifest, self.rows = inputs(folder, selected)
        self.refuse("scope promotion")

    def test_repaired_model_digest_and_identity_still_fail_literal_scope(self):
        selected = docs()
        artifact = selected["native_fixtures"]["true"]
        artifact["model_text"] = artifact["model_text"].replace("Init == n = 0", "Init == n = 1")
        artifact["model_digest"] = r.sha(artifact["model_text"].encode())
        artifact["artifact_digest"] = r.sha(
            r.canonical(
                {
                    k: v
                    for k, v in artifact.items()
                    if k
                    not in (
                        "artifact_digest",
                        "model_text",
                        "tlc_config_text",
                        "apalache_config_text",
                    )
                }
            )
        )
        with self.assertRaisesRegex(r.Refusal, "literal model"):
            r.reconcile(selected, r.repaired_pins(selected))

